def split(cells):
    rs=sorted(set(r for r,_ in cells))
    cuts=[a for a,b in zip(rs,rs[1:]) if b-a>=2]
    segs=[];start=0
    for cut in cuts: segs.append((start,cut)); start=cut+1
    segs.append((start,max(rs)+1))
    res=[]
    for s_,e_ in segs:
        blk=[c_ for c_ in cells if s_[0]<=c_[0]<e_]
        if any(s_[0]<=r<e_ for r,_ in [ (r_) for r_ in cells]) or bool(blk): res.append(blk)
    return res
